package com.rnd.app.entity;
import lombok.*; import org.hibernate.annotations.CreationTimestamp; import javax.persistence.*; import java.time.Instant;
@Entity @Table(name="export_jobs") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class ExportJob { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="project_id",nullable=false)private Long projectId; @Column(name="creator_id",nullable=false)private Long creatorId; @Column(nullable=false,length=16)private String status; @Column(name="request_json",nullable=false,columnDefinition="TEXT")private String requestJson; @Column(name="file_name")private String fileName; @Column(name="storage_path")private String storagePath; @Column(name="expires_at")private Instant expiresAt; @CreationTimestamp @Column(name="created_at",updatable=false)private Instant createdAt; }
